const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-70.647985, -34.752733]);
  const basin = point.buffer(15000); // 15km buffer to capture basin area

  const date2021 = ee.Date('2021-12-18');
  const date2023 = ee.Date('2023-12-18');

  // 2. Data Acquisition - MODIS Snow Cover
  const getSnowData = (date) => {
    return ee.ImageCollection('MODIS/061/MOD10A1')
      .filterBounds(basin)
      .filterDate(date, date.advance(1, 'day'))
      .select('NDSI_Snow_Cover');
  };

  let col2021 = getSnowData(date2021);
  let col2023 = getSnowData(date2023);

  const size2021 = col2021.size().getInfo();
  const size2023 = col2023.size().getInfo();

  console.log(`2021 Images: ${size2021}`);
  console.log(`2023 Images: ${size2023}`);

  // Fallback to MYD10A1 (Aqua) if Terra data missing
  if (size2021 === 0) {
    col2021 = ee.ImageCollection('MODIS/061/MYD10A1')
      .filterBounds(basin)
      .filterDate(date2021, date2021.advance(1, 'day'))
      .select('NDSI_Snow_Cover');
    const newSize = col2021.size().getInfo();
    console.log(`2021 Fallback (Aqua) Images: ${newSize}`);
    if (newSize === 0) {
      console.log('No data for 2021 after fallback.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  if (size2023 === 0) {
    col2023 = ee.ImageCollection('MODIS/061/MYD10A1')
      .filterBounds(basin)
      .filterDate(date2023, date2023.advance(1, 'day'))
      .select('NDSI_Snow_Cover');
    const newSize = col2023.size().getInfo();
    console.log(`2023 Fallback (Aqua) Images: ${newSize}`);
    if (newSize === 0) {
      console.log('No data for 2023 after fallback.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Processing - Get first image and calculate snow extent
  const img2021 = col2021.first();
  const img2023 = col2023.first();

  // Snow pixels are where NDSI_Snow_Cover >= 10 (10% snow cover threshold)
  const snow2021 = img2021.gte(10);
  const snow2023 = img2023.gte(10);

  // 4. Calculate snow extent (area covered by snow)
  const stats2021 = snow2021.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: basin,
    scale: 500,
    maxPixels: 1e9
  });

  const stats2023 = snow2023.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: basin,
    scale: 500,
    maxPixels: 1e9
  });

  const count2021 = snow2021.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: basin,
    scale: 500,
    maxPixels: 1e9
  });

  const snowPixels2021 = stats2021.get('NDSI_Snow_Cover').getInfo();
  const snowPixels2023 = stats2023.get('NDSI_Snow_Cover').getInfo();
  const totalPixels = count2021.get('NDSI_Snow_Cover').getInfo();

  console.log(`Total pixels analyzed: ${totalPixels}`);
  console.log(`2021 Snow pixels: ${snowPixels2021}`);
  console.log(`2023 Snow pixels: ${snowPixels2023}`);

  // 5. Validation & Final Answer
  if (totalPixels === 0) {
    console.log('No valid pixels in region.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (snowPixels2021 === null || snowPixels2023 === null || 
      isNaN(snowPixels2021) || isNaN(snowPixels2023)) {
    console.log('Calculation failed - invalid results.');
    console.log('<answer>C3</answer>');
    return;
  }

  const snowExtent2021 = (snowPixels2021 / totalPixels * 100).toFixed(2);
  const snowExtent2023 = (snowPixels2023 / totalPixels * 100).toFixed(2);

  console.log(`2021 Snow extent: ${snowExtent2021}%`);
  console.log(`2023 Snow extent: ${snowExtent2023}%`);

  if (snowPixels2023 > snowPixels2021) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
